const response = $input.first().json;

// 从数据格式化节点获取回调信息
const formattedData = $('数据格式化').first().json;
const callback = formattedData._callback || {};

try {
  // 提取AI响应内容
  let content = response.output || response.text || '';

  // 清理JSON字符串
  content = content.trim();

  // 移除可能的markdown代码块标记
  if (content.startsWith('```json')) {
    content = content.slice(7);
  } else if (content.startsWith('```')) {
    content = content.slice(3);
  }
  if (content.endsWith('```')) {
    content = content.slice(0, -3);
  }
  content = content.trim();

  // 尝试找到JSON对象
  const jsonStart = content.indexOf('{');
  const jsonEnd = content.lastIndexOf('}');
  if (jsonStart !== -1 && jsonEnd !== -1) {
    content = content.slice(jsonStart, jsonEnd + 1);
  }

  // 解析JSON
  const tripPlan = JSON.parse(content);

  return [{
    json: {
      success: true,
      message: "旅行计划生成成功",
      data: tripPlan,
      _callback: callback
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      message: "解析旅行计划失败: " + error.message,
      raw_response: response.output || response.text || JSON.stringify(response),
      error: error.message,
      _callback: callback
    }
  }];
}

// 接收AI行程规划的响应数据并准备路径查询
// 输入格式应与"解析AI响应"节点输出一致

const input = $input.first().json;

// 配置API密钥
const config = {
  AMAP_API_KEY: 'c900719280603182cda1c3d75658da08'
};

// 获取回调信息
const callback = input._callback || {};

// 验证输入数据
if (!input.success || !input.data || !input.data.days) {
  return [{
    json: {
      success: false,
      message: '输入数据格式错误，需要包含days数组',
      _config: config,
      _callback: callback
    }
  }];
}

const days = input.data.days;
const routeQueries = [];
let previousDayLastLocation = null;

for (let dayIndex = 0; dayIndex < days.length; dayIndex++) {
  const day = days[dayIndex];
  const planning = day.planning || [];

  // 过滤出有有效坐标的地点
  const locations = planning
    .filter(p => p.location && p.location.longitude && p.location.latitude)
    .map(p => ({
      name: p.name,
      type: p.type,
      coord: `${p.location.longitude},${p.location.latitude}`
    }));

  // 如果是第二天及以后，从前一天最后一个地点开始（跨天衔接）
  if (previousDayLastLocation && dayIndex > 0) {
    locations.unshift(previousDayLastLocation);
  }

  // 至少需要2个地点才能规划路径
  if (locations.length >= 2) {
    const origin = locations[0].coord;
    const destination = locations[locations.length - 1].coord;
    // 中间地点作为途经点，用分号分隔
    const waypoints = locations.slice(1, -1).map(l => l.coord).join(';');

    routeQueries.push({
      dayIndex,
      date: day.date,
      origin,
      destination,
      waypoints: waypoints || '',
      locationNames: locations.map(l => l.name),
      locationCount: locations.length,
      _config: config,
      _originalData: input,
      _callback: callback
    });
  }

  // 保存当天最后一个地点供下一天使用
  if (locations.length > 0) {
    previousDayLastLocation = locations[locations.length - 1];
  }
}

// 如果没有可查询的路径，直接返回原数据
if (routeQueries.length === 0) {
  return [{
    json: {
      success: true,
      message: '没有足够的地点进行路径规划',
      data: input.data,
      route_info: [],
      _config: config,
      _callback: callback
    }
  }];
}

// 返回多个查询项，每天一个
return routeQueries.map(q => ({ json: q }));

// 处理所有路径查询结果并整合到原始数据中
const allItems = $input.all();
let originalData = null;
let callback = {};
const routeResults = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i].json;

  // 获取原始输入数据（从准备路径查询数据节点）
  const preparedData = $('准备路径查询数据').all()[i]?.json;

  if (!originalData && preparedData?._originalData) {
    originalData = preparedData._originalData;
  }

  // 获取回调信息
  if (!callback.url && preparedData?._callback) {
    callback = preparedData._callback;
  }

  // 解析路径规划API响应
  if (item.status === '1' && item.route) {
    const paths = item.route.paths || [];
    const mainPath = paths[0] || {};

    // 提取费用信息
    const cost = mainPath.cost || {};

    // 提取每段步骤信息
    const steps = (mainPath.steps || []).map((step, index) => {
      const stepCost = step.cost || {};
      return {
        segment_index: index,
        instruction: step.instruction || '',
        road: step.road || '',
        distance: parseInt(step.distance) || 0,
        duration: Math.round((parseInt(stepCost.duration) || parseInt(step.duration) || 0) / 60),
        tolls: parseFloat(stepCost.tolls) || 0,
        toll_distance: parseInt(stepCost.toll_distance) || 0,
        action: step.action || ''
      };
    });

    routeResults.push({
      day_index: preparedData?.dayIndex ?? i,
      date: preparedData?.date || '',
      location_names: preparedData?.locationNames || [],
      location_count: preparedData?.locationCount || 0,
      // 总体信息
      total_distance: parseInt(mainPath.distance) || 0,
      total_duration: Math.round((parseInt(cost.duration) || parseInt(mainPath.duration) || 0) / 60),
      // 费用信息
      toll_cost: parseFloat(cost.tolls) || parseFloat(mainPath.tolls) || 0,
      toll_distance: parseInt(cost.toll_distance) || parseInt(mainPath.toll_distance) || 0,
      traffic_lights: parseInt(cost.traffic_lights) || parseInt(mainPath.traffic_lights) || 0,
      // 路段详情
      segments: steps,
      // 策略信息
      strategy: mainPath.strategy || ''
    });
  } else {
    // API调用失败时记录错误
    routeResults.push({
      day_index: preparedData?.dayIndex ?? i,
      date: preparedData?.date || '',
      location_names: preparedData?.locationNames || [],
      error: item.info || '路径规划查询失败',
      status: item.status
    });
  }
}

// 构建最终响应
const response = {
  success: true,
  message: '路径规划查询完成',
  data: originalData?.data || {},
  route_info: routeResults,
  summary: {
    total_days: routeResults.length,
    total_distance: routeResults.reduce((sum, r) => sum + (r.total_distance || 0), 0),
    total_duration: routeResults.reduce((sum, r) => sum + (r.total_duration || 0), 0),
    total_toll_cost: routeResults.reduce((sum, r) => sum + (r.toll_cost || 0), 0),
    total_traffic_lights: routeResults.reduce((sum, r) => sum + (r.traffic_lights || 0), 0)
  },
  _callback: callback
};

// 将路径信息也写入data中
if (response.data) {
  response.data.route_info = routeResults;
  response.data.route_summary = response.summary;
}

return [{ json: response }];
